from pathlib import Path
import shutil, json, hashlib
root=Path(__file__).resolve().parents[1]; a=root/'assets'; a.mkdir(exist_ok=True)
src=root/'sources/assets/cell-reference/wellcome-B0007852-760.jpg'; dst=a/'ch01-cell-reference.jpg'; shutil.copyfile(src,dst)
metadata=json.loads((src.parent/'metadata.json').read_text(encoding='utf-8')); metadata['public_file']=dst.name; metadata['modifications']='None to JPEG; displayed at reduced resolution with separate labels.'; assert hashlib.sha256(dst.read_bytes()).hexdigest().upper()==metadata['sha256']
tissue_src=root/'sources/assets/tissue-reference/wellcome-B0009427-760.jpg'; tissue_dst=a/'ch01-cell-tissue-reference.jpg'; shutil.copyfile(tissue_src,tissue_dst)
tissue=json.loads((tissue_src.parent/'metadata.json').read_text(encoding='utf-8')); tissue['public_file']=tissue_dst.name; tissue['modifications']='None to JPEG; displayed at reduced resolution, full field retained.'; assert hashlib.sha256(tissue_dst.read_bytes()).hexdigest().upper()==tissue['sha256']; metadata['tissue_reference']=tissue
(a/'ch01-cell-reference.json').write_text(json.dumps(metadata,indent=2)+'\n',encoding='utf-8')
